  1 | import { useCallback, useRef } from "react";
  2 | import jsmediatags from "jsmediatags";
  3 | import type { Track } from "../types";
  4 | 
  5 | export interface MetadataResult {
  6 |   title?: string;
  7 |   artist?: string;
  8 |   album?: string;
  9 |   coverUrl?: string;
 10 |   duration: number;
 11 | }
 12 | 
 13 | /**
 14 |  * Hook para extrair metadados (ID3 tags) de arquivos de áudio.
 15 |  * Usa a biblioteca jsmediatags para ler tags de MP3, FLAC, etc.
 16 |  */
 17 | export function useMetadata() {
 18 |   const coverUrlsRef = useRef<Map<string, string>>(new Map());
 19 | 
 20 |   /**
 21 |    * Extrai metadados de um arquivo de áudio.
 22 |    * Retorna um objeto com title, artist, album, coverUrl e duration.
 23 |    */
 24 |   const extractMetadata = useCallback(
 25 |     (file: File): Promise<MetadataResult> => {
 26 |       return new Promise((resolve) => {
 27 |         // Fallback: usar nome do arquivo se não conseguir ler tags
 28 |         const fallback: MetadataResult = {
 29 |           title: file.name.replace(/\.[^/.]+$/, ""),
 30 |           duration: 0,
 31 |         };
 32 | 
 33 |         // Só tenta ler tags para formatos suportados
 34 |         const supportedTypes = ["audio/mpeg", "audio/mp3", "audio/flac", "audio/ogg", "audio/wav"];
 35 |         if (!supportedTypes.includes(file.type)) {
 36 |           resolve(fallback);
 37 |           return;
 38 |         }
 39 | 
 40 |         jsmediatags.read(file, {
 41 |           onSuccess: (data) => {
 42 |             const tags = data.tags;
 43 |             let coverUrl: string | undefined;
 44 | 
 45 |             // Converte a capa do álbum (se existir) para data URL
 46 |             if (tags.picture) {
 47 |               const { data: pictureData, format } = tags.picture;
 48 |               const base64 = arrayBufferToBase64(pictureData);
 49 |               const mimeType = format || "image/jpeg";
 50 |               coverUrl = `data:${mimeType};base64,${base64}`;
 51 | 
 52 |               // Armazena para evitar recriação
 53 |               const key = file.name + file.size;
 54 |               coverUrlsRef.current.set(key, coverUrl);
 55 |             }
 56 | 
 57 |             resolve({
 58 |               title: tags.title || fallback.title,
 59 |               artist: tags.artist,
 60 |               album: tags.album,
 61 |               coverUrl,
 62 |               duration: tags.duration ?? 0,
 63 |             });
 64 |           },
 65 |           onError: () => {
 66 |             // Se falhar, usa o fallback
 67 |             resolve(fallback);
 68 |           },
 69 |         });
 70 |       });
 71 |     },
 72 |     []
 73 |   );
 74 | 
 75 |   /**
 76 |    * Processa uma lista de arquivos e retorna Tracks com metadados enriquecidos.
 77 |    */
 78 |   const processFiles = useCallback(
 79 |     async (files: File[]): Promise<Track[]> => {
 80 |       const tracks: Track[] = [];
 81 |       const now = Date.now();
 82 | 
 83 |       for (let i = 0; i < files.length; i++) {
 84 |         const file = files[i];
 85 |         const url = URL.createObjectURL(file);
 86 |         const metadata = await extractMetadata(file);
 87 | 
 88 |         tracks.push({
 89 |           id: `local-${now}-${i}`,
 90 |           title: metadata.title || file.name.replace(/\.[^/.]+$/, ""),
 91 |           artist: metadata.artist,
 92 |           album: metadata.album,
 93 |           duration: metadata.duration,
 94 |           coverUrl: metadata.coverUrl,
 95 |           src: url,
 96 |         });
 97 |       }
 98 | 
 99 |       return tracks;
100 |     },
101 |     [extractMetadata]
102 |   );
103 | 
104 |   /**
105 |    * Libera URLs de capas do álbum para evitar vazamento de memória.
106 |    */
107 |   const cleanupCoverUrls = useCallback(() => {
108 |     coverUrlsRef.current.clear();
109 |   }, []);
110 | 
111 |   return {
112 |     extractMetadata,
113 |     processFiles,
114 |     cleanupCoverUrls,
115 |   };
116 | }
117 | 
118 | function arrayBufferToBase64(buffer: ArrayBuffer): string {
119 |   const bytes = new Uint8Array(buffer);
120 |   let binary = "";
121 |   for (let i = 0; i < bytes.length; i++) {
122 |     binary += String.fromCharCode(bytes[i]);
123 |   }
124 |   return btoa(binary);
125 | }
